function validate([x, y, points]) {
  const inRange = v => Number.isInteger(v) && v >= 1 && v <= 10000;
  if (!inRange(x) || !inRange(y)) return 'x and y are integers from 1 to 10^4.';
  if (!Array.isArray(points) || points.length < 1 || points.length > 10000) return 'points needs 1 to 10^4 points.';
  if (points.some(p => !Array.isArray(p) || p.length !== 2 || !inRange(p[0]) || !inRange(p[1]))) return 'Each point is [a, b] with integers from 1 to 10^4.';
  return null;
}

