function nearestValidPoint(x, y, points) {
  let bestIndex = -1;
  let bestDistance = Infinity;

  for (let i = 0; i < points.length; i++) {
    const [a, b] = points[i];
    if (a !== x && b !== y) {
      continue;
    }
    const distance = Math.abs(a - x) + Math.abs(b - y);
    if (distance < bestDistance) {
      bestDistance = distance;
      bestIndex = i;
    }
  }
  return bestIndex;
}

