function nearestValidPoint(x, y, points) {
  const valid = [];
  points.forEach(([a, b], index) => {
    if (a === x || b === y) valid.push({ index, distance: Math.abs(a - x) + Math.abs(b - y) });
  });
  if (valid.length === 0) return -1;
  valid.sort((p, q) => p.distance - q.distance || p.index - q.index);
  return valid[0].index;
}

