function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const limit = large ? 10000 : 6;
  const x = int(1, limit);
  const y = int(1, limit);
  const n = large ? 2000 : int(1, 8);
  const shareRate = large ? (rand() < 0.2 ? 0 : 0.05) : rand();
  const points = [];
  for (let i = 0; i < n; i++) {
    const roll = rand();
    if (roll < shareRate / 2) points.push([x, int(1, limit)]);
    else if (roll < shareRate) points.push([int(1, limit), y]);
    else points.push([int(1, limit), int(1, limit)]);
  }
  return [x, y, points];
}
